impl BinaryEncode for PwrightMouseErrorRef<'_> {
    fn encode_binary(&self, writer: &mut BinaryWriter, context: &mut BinaryValueContext) -> Result<(), BinaryValueEncodeError> {
        context.within_message("pwright.mouse.error", |context| {
            <PwrightCommonFailureKind as BinaryEncode>::encode_binary(&self.failure_kind, writer, context)?;
            pwright_codec_binary::encode_utf8_constrained(writer, context, "pwright.mouse.error.message", self.message, BinarySizeRange::new(None, Some(4096_u32)))?;
            writer.u8(u8::from(self.details.is_some()))?;
            if let Some(value) = &self.details {
                <PwrightMouseErrorDetailsRef as BinaryEncode>::encode_binary(value, writer, context)?;
            }
            Ok(())
        })
    }
}

impl BinaryEncode for PwrightMouseErrorDetailsRef<'_> {
    fn encode_binary(&self, writer: &mut BinaryWriter, context: &mut BinaryValueContext) -> Result<(), BinaryValueEncodeError> {
        context.within_message("pwright.mouse.error_details", |context| {
            match self {
                Self::InvalidArgument { message } => {
                    writer.u8(0)?;
                    pwright_codec_binary::encode_utf8_constrained(writer, context, "pwright.mouse.error_details.invalid_argument.message", message, BinarySizeRange::new(None, Some(4096_u32)))?;
                    Ok(())
                }
                Self::Resource { message } => {
                    writer.u8(1)?;
                    pwright_codec_binary::encode_utf8_constrained(writer, context, "pwright.mouse.error_details.resource.message", message, BinarySizeRange::new(None, Some(4096_u32)))?;
                    Ok(())
                }
                Self::Backend { message } => {
                    writer.u8(2)?;
                    pwright_codec_binary::encode_utf8_constrained(writer, context, "pwright.mouse.error_details.backend.message", message, BinarySizeRange::new(None, Some(4096_u32)))?;
                    Ok(())
                }
            }
        })
    }
}

impl BinaryEncode for PwrightMouseOutcomeRef<'_> {
    fn encode_binary(&self, writer: &mut BinaryWriter, context: &mut BinaryValueContext) -> Result<(), BinaryValueEncodeError> {
        context.within_message("pwright.mouse.outcome", |context| {
            match self {
                Self::Success => {
                    writer.u8(0)?;
                    Ok(())
                }
                Self::Error { error } => {
                    writer.u8(1)?;
                    <PwrightMouseErrorRef as BinaryEncode>::encode_binary(error, writer, context)?;
                    Ok(())
                }
            }
        })
    }
}

impl From<PwrightMouseErrorDetails> for PublicMouseErrorDetails {
    fn from(value: PwrightMouseErrorDetails) -> Self {
        match value {
            PwrightMouseErrorDetails::InvalidArgument { message } => Self::InvalidArgument(message),
            PwrightMouseErrorDetails::Resource { message } => Self::Resource(message),
            PwrightMouseErrorDetails::Backend { message } => Self::Backend(message),
        }
    }
}

impl From<PublicMouseErrorDetails> for PwrightMouseErrorDetails {
    fn from(value: PublicMouseErrorDetails) -> Self {
        match value {
            PublicMouseErrorDetails::InvalidArgument(message) => Self::InvalidArgument { message },
            PublicMouseErrorDetails::Resource(message) => Self::Resource { message },
            PublicMouseErrorDetails::Backend(message) => Self::Backend { message },
        }
    }
}

